void check(const std::string& what, int got, int expected) {
    if (got == expected) {
        std::cout << "PASS " << what << '\n';
    } else {
        std::cout << "FAIL " << what << ": expected " << expected << ", got " << got << '\n';
    }
}

int main() {
    check("empty table", bill_cents(0, 0), 0);
    check("one soup", bill_cents(1, 0), 400);
    check("one pie", bill_cents(0, 1), 300);
    check("two soups, one pie", bill_cents(2, 1), 1100);
}

