#include <iostream>
#include <vector>

int bill_cents(int soups, int pies) {
    return soups * 400 + pies * 300;
}

struct Case {
    int soups;
    int pies;
    int expected;
};

int main() {
    std::vector<Case> cases{{0, 0, 0}, {1, 0, 400}, {0, 2, 600}, {2, 1, 1100}, {3, 2, 1600}};
    for (const Case& c : cases) {
        int got = bill_cents(c.soups, c.pies);
        std::cout << c.soups << ' ' << c.pies << ' ' << c.expected << ' ' << got << ' '
                  << (got == c.expected ? "PASS" : "FAIL") << '\n';
    }
}

